export const MOMENT_TEST = "// Differential property-based tests: moment (old) vs dayjs (new).\n// Generated by Revenant, recipe moment-to-dayjs. Run with: npx vitest run\nimport dayjs from \"dayjs\";\nimport fc from \"fast-check\";\nimport moment from \"moment\";\nimport { describe, expect, it } from \"vitest\";\n\n// Keep generated instants inside a range where both libraries agree on the calendar.\nconst date = fc.date({ min: new Date(\"1971-01-01T00:00:00Z\"), max: new Date(\"2099-12-31T00:00:00Z\"), noInvalidDate: true });\nconst unit = fc.constantFrom(\"year\", \"month\", \"week\", \"day\", \"hour\", \"minute\", \"second\");\nconst startUnit = fc.constantFrom(\"year\", \"month\", \"day\", \"hour\", \"minute\");\nconst FORMATS = [\"YYYY-MM-DD\", \"YYYY-MM-DD HH:mm:ss\", \"DD/MM/YYYY\", \"MMM D, YYYY\", \"MMMM D YYYY\", \"dddd\", \"ddd, D MMM\", \"h:mm A\", \"HH:mm\", \"YY\", \"M/D/YYYY\", \"d\"];\nconst format = fc.constantFrom(...FORMATS);\n\ndescribe(\"moment vs dayjs (differential)\", () => {\n  it(\"format() agrees for the shared token set\", () => {\n    fc.assert(fc.property(date, format, (d, f) => {\n        expect(dayjs(d).format(f)).toBe(moment(d).format(f));\n      }), { numRuns: 200 });\n  });\n\n  it(\"add() and subtract() produce the same instant\", () => {\n    fc.assert(\n      fc.property(date, fc.integer({ min: -500, max: 500 }), unit, (d, n, u) => {\n        const unitName = u as moment.unitOfTime.DurationConstructor;\n        expect(dayjs(d).add(n, u).valueOf()).toBe(moment(d).add(n, unitName).valueOf());\n        expect(dayjs(d).subtract(n, u).valueOf()).toBe(moment(d).subtract(n, unitName).valueOf());\n      }),\n      { numRuns: 200 },\n    );\n  });\n\n  it(\"startOf() and endOf() agree\", () => {\n    fc.assert(\n      fc.property(date, startUnit, (d, u) => {\n        const m = u as moment.unitOfTime.StartOf;\n        expect(dayjs(d).startOf(u).valueOf()).toBe(moment(d).startOf(m).valueOf());\n        expect(dayjs(d).endOf(u).valueOf()).toBe(moment(d).endOf(m).valueOf());\n      }),\n      { numRuns: 200 },\n    );\n  });\n\n  it(\"diff() agrees (truncated toward zero)\", () => {\n    fc.assert(\n      fc.property(date, date, fc.constantFrom(\"day\", \"hour\", \"minute\", \"second\", \"millisecond\"), (a, b, u) => {\n        expect(dayjs(a).diff(b, u)).toBe(moment(a).diff(b, u as moment.unitOfTime.Diff));\n      }),\n      { numRuns: 200 },\n    );\n  });\n\n  it(\"isBefore / isAfter / isSame agree\", () => {\n    fc.assert(\n      fc.property(date, date, (a, b) => {\n        expect(dayjs(a).isBefore(b)).toBe(moment(a).isBefore(b));\n        expect(dayjs(a).isAfter(b)).toBe(moment(a).isAfter(b));\n        expect(dayjs(a).isSame(b)).toBe(moment(a).isSame(b));\n      }),\n      { numRuns: 200 },\n    );\n  });\n\n  it(\"parses ISO strings to the same instant\", () => {\n    fc.assert(fc.property(date, (d) => {\n        expect(dayjs(d.toISOString()).valueOf()).toBe(moment(d.toISOString()).valueOf());\n      }), { numRuns: 200 });\n  });\n\n  it(\"documents the known difference: moment mutates, dayjs does not\", () => {\n    const d = new Date(\"2024-01-31T10:00:00Z\");\n    const m = moment(d);\n    m.add(1, \"day\");\n    const j = dayjs(d);\n    j.add(1, \"day\");\n    expect(m.valueOf()).not.toBe(d.getTime());\n    expect(j.valueOf()).toBe(d.getTime());\n  });\n});\n";
